questionvariables.text:
/* Pools of statements: [id, statement, intended method, accepted methods, likely error, other wrong method, lead for the likely error, explanation]. */
pD: [
 ["D1", "If \\(m\\) and \\(n\\) are odd integers, then \\(mn\\) is odd.", mdir, [mdir, mcon], mexh, mcex, "There are infinitely many pairs of odd numbers, so they cannot be checked one by one.", "It has the form ‘if A, then B’, and A gives something to calculate with: \\(m = 2k + 1\\) and \\(n = 2l + 1\\) give \\(mn = 2(2kl + k + l) + 1\\). A direct proof."],
 ["D2", "For every real number \\(x\\), \\(x^2 - 6x + 10 \\gt 0\\).", mdir, [mdir, mcon], mind, mcex, "Induction proves statements about the integers \\(n = 1, 2, 3, \\ldots\\); here \\(x\\) can be any real number.", "Completing the square gives \\(x^2 - 6x + 10 = (x - 3)^2 + 1\\), which is at least 1 for every real \\(x\\). A direct proof."],
 ["D3", "If \\(x\\) and \\(y\\) are rational numbers, then \\(x + y\\) is rational.", mdir, [mdir, mcon], mexh, mcex, "There are infinitely many rational numbers, so they cannot be checked one by one.", "\\(x = \\dfrac{a}{b}\\) and \\(y = \\dfrac{c}{d}\\) give \\(x + y = \\dfrac{ad + bc}{bd}\\), a fraction of integers with \\(bd \\neq 0\\). A direct proof."]
];
pE: [
 ["E1", "For every integer \\(n\\) with \\(1 \\le n \\le 5\\), \\(n^2 + n + 17\\) is prime.", mexh, [mexh], mind, mcex, "An induction step would have to show that each value being prime makes the next one prime, and nothing makes that true. But there are only five cases.", "There are only five cases: 19, 23, 29, 37 and 47 are all prime. Checking every case is a complete proof: a proof by exhaustion."],
 ["E2", "Each of the numbers 13, 17, 29 and 37 is the sum of two square numbers.", mexh, [mexh], mdir, mcex, "There is no general rule here to start from: each number has to be checked.", "There are four cases: \\(13 = 4 + 9\\), \\(17 = 1 + 16\\), \\(29 = 4 + 25\\) and \\(37 = 1 + 36\\). A proof by exhaustion."],
 ["E3", "For every integer \\(n\\) with \\(1 \\le n \\le 6\\), \\(n^2 - n + 11\\) is prime.", mexh, [mexh], mind, mcex, "An induction step would have to show that each value being prime makes the next one prime, and nothing makes that true. But there are only six cases.", "There are only six cases: 11, 13, 17, 23, 31 and 41 are all prime. A proof by exhaustion. (For \\(n = 11\\) the value is \\(121 = 11^2\\), so the statement could not be extended to every \\(n\\).)"]
];
pI: [
 ["I1", "The sequence with \\(u_1 = 3\\) and \\(u_{n+1} = 2u_n - 1\\) satisfies \\(u_n = 2^n + 1\\) for every positive integer \\(n\\).", mind, [mind], mdir, mexh, "Each term is defined only through the term before it, so there is no formula to start a direct calculation from.", "Each case is built from the one before: if \\(u_k = 2^k + 1\\), then \\(u_{k+1} = 2(2^k + 1) - 1 = 2^{k+1} + 1\\). With \\(u_1 = 3 = 2^1 + 1\\), this is a proof by induction."],
 ["I2", "The sequence with \\(u_1 = 1\\) and \\(u_{n+1} = 3u_n + 2\\) satisfies \\(u_n = 2 \\times 3^{n-1} - 1\\) for every positive integer \\(n\\).", mind, [mind], mdir, mexh, "Each term is defined only through the term before it, so there is no formula to start a direct calculation from.", "If \\(u_k = 2 \\times 3^{k-1} - 1\\), then \\(u_{k+1} = 3(2 \\times 3^{k-1} - 1) + 2 = 2 \\times 3^k - 1\\), and \\(u_1 = 1 = 2 \\times 3^0 - 1\\). A proof by induction."],
 ["I3", "The sequence with \\(u_1 = 4\\) and \\(u_{n+1} = 3u_n - 2\\) satisfies \\(u_n = 3^n + 1\\) for every positive integer \\(n\\).", mind, [mind], mdir, mexh, "Each term is defined only through the term before it, so there is no formula to start a direct calculation from.", "If \\(u_k = 3^k + 1\\), then \\(u_{k+1} = 3(3^k + 1) - 2 = 3^{k+1} + 1\\), and \\(u_1 = 4 = 3^1 + 1\\). A proof by induction."]
];
pC: [
 ["C1", "\\(\\sqrt{3}\\) is irrational.", mcon, [mcon], mdir, mind, "‘Irrational’ means ‘not rational’, so there is no equation to start a direct calculation from.", "The statement says that \\(\\sqrt{3} = \\dfrac{p}{q}\\) is impossible. Assume it holds with \\(\\dfrac{p}{q}\\) in simplest form: then \\(p^2 = 3q^2\\), and \\(p\\) and \\(q\\) both turn out to be multiples of 3, a contradiction. A proof by contradiction."],
 ["C2", "\\(\\log_2 3\\) is irrational.", mcon, [mcon], mdir, mind, "‘Irrational’ means ‘not rational’, so there is no equation to start a direct calculation from.", "Assume \\(\\log_2 3 = \\dfrac{p}{q}\\) with \\(p\\) and \\(q\\) positive integers. Then \\(2^p = 3^q\\): an even number equal to an odd number, a contradiction. A proof by contradiction."],
 ["C3", "\\(\\sqrt{6}\\) is irrational.", mcon, [mcon], mdir, mind, "‘Irrational’ means ‘not rational’, so there is no equation to start a direct calculation from.", "Assume \\(\\sqrt{6} = \\dfrac{p}{q}\\) in simplest form. Then \\(p^2 = 6q^2\\) is even, so \\(p = 2k\\), and \\(2k^2 = 3q^2\\), so \\(q\\) is even too: a contradiction. A proof by contradiction."]
];
pX: [
 ["X1", "For every positive integer \\(n\\), \\(n^2 + n + 1\\) is prime.", mcex, [mcex], mind, mdir, "Test the statement before you try to prove it.", "It is false: for \\(n = 4\\), \\(n^2 + n + 1 = 21 = 3 \\times 7\\). One counterexample disproves it, and no method can prove a false statement."],
 ["X2", "For every positive integer \\(n\\), \\(2^n + 1\\) is prime.", mcex, [mcex], mind, mdir, "Test the statement before you try to prove it.", "It is false: for \\(n = 3\\), \\(2^3 + 1 = 9 = 3 \\times 3\\). A disproof by counterexample."],
 ["X3", "Every positive integer less than 10 is the sum of at most three square numbers.", mcex, [mcex], mexh, mdir, "Checking each case is the right start, but one of the cases fails.", "It is false: the square numbers up to 7 are 1 and 4, and no sum of at most three of them is 7 (\\(4 + 1 + 1 = 6\\) and \\(4 + 4 = 8\\)). Checking the cases finds a counterexample."]
];
pools: [pD, pE, pI, pC, pX];
pick: rand_selection([1, 2, 3, 4, 5], 4);
r1: rand(pools[pick[1]]);
r2: rand(pools[pick[2]]);
r3: rand(pools[pick[3]]);
r4: rand(pools[pick[4]]);
qrows: random_permutation([r1, r2, r3, r4]);
opts(c) := [[mdir, is(c = mdir), "direct proof"], [mexh, is(c = mexh), "proof by exhaustion"], [mind, is(c = mind), "proof by induction"], [mcon, is(c = mcon), "proof by contradiction"], [mcex, is(c = mcex), "disproof by counterexample"]];
/* Wrong-answer feedback never names the right method: the row's lead for the likely error, and nudge (what the chosen method needs) for any other wrong choice. */
nudge(c) := if c = mdir then "A direct proof needs a general argument that leads from what is given to the conclusion. Before looking for one, ask the first questions in the box above: is the statement true, and how many cases does it cover?" else if c = mexh then "A proof by exhaustion checks every case, one by one, so it needs a finite list of cases. Is there such a list here?" else if c = mind then "A proof by induction is for a statement about every positive integer \\(n\\), where each case can be built from the one before. Is this statement like that?" else if c = mcon then "A proof by contradiction assumes that the statement is false and looks for something impossible. Ask the earlier questions in the box above first: is the statement true, how many cases does it cover, and is each case built from the one before?" else "A counterexample disproves a statement that is false. Is this one false? If you cannot find a case in which it fails, look for a proof.";
stmt1: qrows[1][2]; cor1: qrows[1][3]; ok1: qrows[1][4]; diag1: qrows[1][5]; oth1: qrows[1][6]; lead1: qrows[1][7]; expl1: qrows[1][8];
alt1: if is(member(mcon, ok1) and cor1 = mdir) then mcon else cor1;
ta1: opts(cor1);
stmt2: qrows[2][2]; cor2: qrows[2][3]; ok2: qrows[2][4]; diag2: qrows[2][5]; oth2: qrows[2][6]; lead2: qrows[2][7]; expl2: qrows[2][8];
alt2: if is(member(mcon, ok2) and cor2 = mdir) then mcon else cor2;
ta2: opts(cor2);
stmt3: qrows[3][2]; cor3: qrows[3][3]; ok3: qrows[3][4]; diag3: qrows[3][5]; oth3: qrows[3][6]; lead3: qrows[3][7]; expl3: qrows[3][8];
alt3: if is(member(mcon, ok3) and cor3 = mdir) then mcon else cor3;
ta3: opts(cor3);
stmt4: qrows[4][2]; cor4: qrows[4][3]; ok4: qrows[4][4]; diag4: qrows[4][5]; oth4: qrows[4][6]; lead4: qrows[4][7]; expl4: qrows[4][8];
alt4: if is(member(mcon, ok4) and cor4 = mdir) then mcon else cor4;
ta4: opts(cor4);
s_assert(every(lambda([rw], not(member(rw[5], rw[4])) and not(member(rw[6], rw[4])) and is(rw[5] # rw[6])), qrows), true);
